(function () {
  'use strict';
  const sources = {
    inheritance: { title: 'Recursive Improvement Without Recursive Authority', file: 'sources/inheritance.html', detail: 'Qualified Inheritance and Causal Reuse in Alignment Development', doi: 'https://doi.org/10.5281/zenodo.23067211' },
    alignment: { title: 'Towards Recursively Self-Improving Alignment', file: 'sources/alignment.html', detail: 'Alignment as a Dynamic Property of Contextual State Transitions' },
    enquiry: { title: 'Constructive Enquiry and Acquired Model Extension', file: 'sources/enquiry.html', detail: 'Bounded development under fixed authority', doi: 'https://doi.org/10.5281/zenodo.23157200' },
    distinctions: { title: 'Learning What Must Be Distinguished', file: 'sources/distinctions.html', detail: 'Accountable Refinement Abstraction and Reuse Under Changing Obligations', doi: 'https://doi.org/10.5281/zenodo.23090566' },
    book: { title: 'The Aligned Signal', file: 'sources/aligned-signal.html', detail: 'Forthcoming book · manuscript citation; private reading copy omitted' }
  };
  const definitions = {
    mersia: { title: 'MeRSIA', aliases: ['MeRSIA'], plain: 'Meta-recursively self-improving alignment: the proposed capacity to improve how a system improves its alignment, with context and alignment mechanics woven into its computational trajectory.', math: 'Research programme. This prototype has no established relative-rate theorem. Such a theorem or experiment needs specified transition contracts, an alignment invariant, a charged resource measure, and a comparison with other capability development.', refs: [['book',27,'Preface: MeRSIA proposal']] },
    alignment: { title: 'Alignment mechanics', aliases: ['alignment mechanics','alignment'], plain: 'The conditions connecting a justified judgment to permitted consequences, while preserving the responsibilities that continue through change.', math: 'In the broader paper, admitted transitions must preserve an invariant I(z). Release(u,z) requires Current(q,z), Covers(q,u,z), an accepting evaluator and OwnerAdmits(u,z). Here we instantiate a narrower finite receiving check.', refs: [['alignment',3,'§§3–4, release condition and preservation'],['alignment',4,'Theorem 1, conditional composition']] },
    context: { title: 'Context', aliases: ['context mechanics','context'], plain: 'The circumstances and relationships that determine what evidence means, which distinctions matter, and whether a result may be used now.', math: 'Here: encounter ID, distinct context-bound roots, error allowance b, rule, active coordinates A, access conditions, evidence revision and receiving permission. This is a finite instance, not the full Orchard anatomy.', refs: [['inheritance',14,'Appendix D.1, data and separation of roles'],['alignment',2,'§2, contextual model']] },
    worlds: { title: 'Compatible worlds', aliases: ['compatible worlds','compatible-world','compatible world'], plain: 'Every assignment of safe or harmful to the 32 situations that could fit the reports under the declared error allowance.', math: 'W_b(E) = { f : Ω → {0,1} | Σ_x n_x^(1−f(x)) ≤ b }, with Ω = {0,…,31}. World count uses exact dynamic programming; unobserved situations remain free.', refs: [['inheritance',2,'Finite Evidence and Receiving Semantics'],['inheritance',15,'Appendix D.2']] },
    root: { title: 'Evidence root', aliases: ['evidence roots','evidence root','distinct roots'], plain: 'A distinct, context-bound report source. Copying the same identified report does not create another independent root.', math: 'A report is (root, context, state, harmful). Each distinct root is counted once. Conflicting reuse, wrong context and a fourth root at one point are rejected. Root identity is supplied; this prototype does not authenticate an issuer.', refs: [['inheritance',14,'Appendix D.1']] },
    allowance: { title: 'Error allowance', aliases: ['error allowance','error bound','false-report allowance'], plain: 'An externally supplied ceiling on how many distinct reports may be false across the entire encounter.', math: 'b ∈ {0,1,2} in this playground. The paper fixture uses b=1. Changing b changes W_b(E); it is a change of premise, not evidence that the new premise is true.', refs: [['inheritance',2,'Finite evidence model'],['inheritance',15,'Appendix D.2, b=1 fixture']] },
    floor: { title: 'Feasibility floor', aliases: ['feasibility floor','forced errors','minimum false reports'], plain: 'The smallest number of false reports that any assignment must have. If the allowance lies below this floor, no world fits the evidence.', math: 'm_x = min(n_x⁰,n_x¹); M = Σ_x m_x. W_b(E) is nonempty exactly when M ≤ b. A conflicting safe/harmful anchor contributes one to M.', refs: [['inheritance',2,'Finite evidence semantics'],['inheritance',15,'Appendix D.2']] },
    local: { title: 'Local rule', aliases: ['local rule'], plain: 'A point judgment based on enough agreeing reports at that particular situation, with a consistency guard.', math: 'Claim v only when n_x^v > b, and return a label only when exactly one claim holds and M ≤ b. At b=1 a single target report is insufficient.', refs: [['inheritance',15,'Appendix D.2, LOCAL=(local,1,true)']] },
    global: { title: 'Context-wide evidence rule', aliases: ['context-wide evidence rule','context-wide rule'], plain: 'A rule that uses the error forced elsewhere in the same context to assess this situation.', math: 'Let e_x=M−m_x. Claim v when n_x^v+e_x>b, with M≤b and exactly one claim. Equivalently, V_x(E)={v : n_x^(1−v)+e_x≤b} is a singleton. This equivalence is checked in the declared count grammar.', refs: [['inheritance',15,'Appendix D.2, GLOBAL rule and bridge']] },
    point: { title: 'Point label', aliases: ['warranted point labels','point labels','point label'], plain: 'A judgment about one full situation before any information is merged by the receiving view.', math: 'P(x) ∈ {0,1,⊥}. A decisive P(x)=v is sound if every f∈W_b(E) has f(x)=v and W_b(E)≠∅. ⊥ means unresolved.', refs: [['inheritance',15,'Appendix D.2']] },
    receiving: { title: 'Receiving label', aliases: ['receiving labels','receiving label'], plain: 'The answer a receiving decision can use after the view has grouped situations together.', math: 'D_A(x)=v iff every y with π_A(y)=π_A(x) has P(y)=v≠⊥; otherwise D_A(x)=⊥. Every member of the class participates, including unobserved points.', refs: [['inheritance',15,'Appendix D.3']] },
    view: { title: 'Receiving view', aliases: ['receiving view','context map','refined view','coarse view'], plain: 'The distinctions from the retained situation that are actually exposed to a receiving decision.', math: 'π_A(x) retains bits in A. Initially A={1,2,3,4}; after lawful refinement A={0,1,2,3,4}. The carrier stays five bits in both cases.', refs: [['inheritance',5,'Worked Coupled Encounter'],['inheritance',15,'Appendix D.3'],['distinctions',3,'Adequate projections and inadequacy witnesses']] },
    fibre: { title: 'Receiving class (fibre)', aliases: ['receiving classes','receiving class','fibre'], plain: 'All full situations that look identical through the receiving view.', math: '[x]_A = {y∈Ω : π_A(y)=π_A(x)}. Initially [0]_A={0,1}. The full five-bit view has 32 singleton classes.', refs: [['inheritance',15,'Appendix D.3'],['distinctions',3,'Adequacy and quotient distinctions']] },
    bit: { title: 'Missing bit', aliases: ['missing bit','bit 0'], plain: 'The already-retained coordinate that distinguishes the two target situations but is initially absent from the receiving view.', math: 'x=0 has bit₀(x)=0; x=1 has bit₀(x)=1. Exposing coordinate 0 refines their shared fibre into two singleton fibres. Permission to expose it is supplied.', refs: [['inheritance',5,'Worked Coupled Encounter']] },
    decisive: { title: 'Decisive coverage', aliases: ['decisive target cases','decisive coverage','decisive'], plain: 'How many target cases have a justified, definite receiving answer rather than an unresolved one.', math: 'G(A,P)=Σ_{x∈{0,1}} 1[D_A(x)≠⊥]. The ceiling in this encounter is 2; all other points have zero target weight. This is not a general safety score.', refs: [['inheritance',14,'Appendix D.1, weights'],['inheritance',15,'Appendix D.3, coverage']] },
    unresolved: { title: 'Unresolved', aliases: ['unresolved'], plain: 'The current rule and view do not justify one definite answer. Holding is not the same as proving the operation is harmful.', math: '⊥ denotes an unknown point or receiving label. A receiver returns ⊥ when its class lacks a common decisive point label. Administrative hold does not fulfil a positive service duty.', refs: [['inheritance',15,'Appendices D.2–D.3'],['alignment',3,'Unknown versus warranted rejection']] },
    safe: { title: 'Safe (formal label)', aliases: ['safe'], plain: 'Label 0 in this toy harmfulness model. It is a judgment under declared premises, not a claim of real-world or general AI safety.', math: 'f(x)=0. A receiving label 0 can produce a simulated release only with a current record, current permission, and no known coverage failure.', refs: [['inheritance',2,'Boolean harmfulness model'],['inheritance',15,'Appendix D.3']] },
    harmful: { title: 'Harmful (formal label)', aliases: ['harmful'], plain: 'Label 1 in the toy model. A justified harmful receiving label supports a simulated block.', math: 'f(x)=1. Under the one-error fixture, V_1(E)={1}; after refining the view, D_A(1)=1.', refs: [['inheritance',5,'Worked Coupled Encounter'],['inheritance',15,'Appendix D.3']] },
    permission: { title: 'Current receiving permission', aliases: ['current receiving permission','receiving permission','permission'], plain: 'An external, currently active grant to use a judgment for a receiving action. A repair does not create that grant.', math: 'Permission is an independent Boolean gate in this milestone. Execute ⇒ Permission ∧ CurrentBinding ∧ DecisiveReceivingLabel ∧ ¬KnownCoverageFailure. The visitor controls the grant.', refs: [['inheritance',15,'Appendix D.3'],['alignment',3,'Equation (2), OwnerAdmits']] },
    binding: { title: 'Current binding', aliases: ['current binding','currentness','current record','captured record','captured receiving record'], plain: 'A captured judgment still matches the exact context, evidence roots, assumptions, rule and view being used now.', math: 'Current(q,s) iff q.context=s.context and q.snapshot=Canonical(s). The canonical snapshot binds revision, roots, counts, b, rule, view, access and coverage-validity signal. Exact equality here is not source authentication.', refs: [['inheritance',15,'Appendix D.3, receiving record'],['alignment',3,'Release condition']] },
    stale: { title: 'Stale', aliases: ['stale'], plain: 'A previously captured receiving record no longer matches the state it would be used in.', math: 'q.snapshot ≠ Canonical(s), or the context differs. Execution holds both cases until fresh capture and qualification. Evidence revision prevents remove-and-restore from silently reviving an old record.', refs: [['inheritance',15,'Appendix D.3']] },
    qualification: { title: 'Qualification', aliases: ['qualification','qualified','qualifying'], plain: 'A scoped check that a candidate has the promised behavior and preserves protected judgments under the stated model.', math: 'Milestones 1/2 replay a 320-case rule bridge and protect old decisive labels. Milestones 3/4 replay enquiry trees over every represented (g,K), requiring leaf.K=K. Stage 4 also requires a unique calibration survivor and zero mismatches on a complete 3,100-observation validation scope before expression installation. Stage 5 additionally retains all 26 old programs, checks 312 old denotations and the four supplied Boolean truth rows, and validates each acquired composite on 2,170 measurements. Coverage and issuer authenticity remain separate premises.', refs: [['inheritance',15,'Appendix D.2, rule bridge'],['enquiry',3,'§4.1, finite expression validation'],['alignment',4,'Theorem 1 premises']] },
    preservation: { title: 'Preservation', aliases: ['preservation','preserves','preserving'], plain: 'A repair retains previously justified answers under the same evidence, meanings and premises.', math: 'P_old(x)≠⊥ ⇒ P_new(x)=P_old(x), and likewise for receiving labels. Strict development additionally needs G_new>G_old. A discovered false premise triggers requalification, not blind retention of its old conclusions.', refs: [['inheritance',15,'Appendices D.2–D.4'],['alignment',3,'Equation (3), non-regression']] },
    coupled: { title: 'Coupled repair', aliases: ['coupled repair','both repairs'], plain: 'Two changes whose combination makes receiving decisions possible even though either one alone has zero receiving gain.', math: 'On this fixture G(local,coarse)=G(global,coarse)=G(local,full)=0; G(global,full)=2. Both effects preserve the same E and W_b(E), and require no new receiving permission.', refs: [['inheritance',5,'Worked Coupled Encounter']] },
    threshold: { title: 'Decision threshold', aliases: ['decision threshold','threshold'], plain: 'The numerical boundary determining whether a possible label fits the allowed number of false reports.', math: 'A label v is possible iff c_x(v)+M−m_x≤b, where c_x(v)=n_x^(1−v). A point judgment is decisive only when exactly one label is possible. The chart shows both costs against b.', refs: [['inheritance',15,'Appendix D.2']] },
    coverage: { title: 'Model coverage', aliases: ['model coverage','coverage failure','coverage-validity'], plain: 'Whether the actual situation is included among the worlds the mathematical model allows. Internal agreement can coexist with an excluded reality.', math: 'Coverage requires f_actual∈W_b(E). An external audit can count actual false reports and find Σ_x n_x^(1−f_actual(x))>b. That audited truth is kept out of this experiment’s reasoning and repair search.', refs: [['inheritance',7,'Coverage-failure control'],['enquiry',2,'§2.1, internal disagreement versus coverage failure']] },
    audit: { title: 'Trusted effect audit', aliases: ['trusted audit','effect audit','external audit','audited feedback'], plain: 'A separately warranted observation of what actually happened, used to identify a failure the working model may not detect.', math: 'This playground’s audit is a supplied truth fixture. It compares actual report errors with b and can revoke coverage validity. It is not an authenticated real-world measurement channel, and it does not grant authority.', refs: [['enquiry',3,'§4, acquisition from audited failure'],['inheritance',7,'Soundness and separate coverage failure']] },
    inheritance: { title: 'Qualified inheritance', aliases: ['qualified inheritance','inheritance'], plain: 'An acquired construction method becomes available in a new context, where it must contribute to a freshly checked repair. Evidence and permission do not transfer with it.', math: 'Milestone 2: replay a scoped acquisition of Π₂, load it into a child with E=∅ and no receiving grants, then supply new context-bound E. Removing the rule constructor delays positive composite acquisition from one to two charged rounds in this toy grammar. Direct search remains an effective zero-acquisition-round control.', refs: [['inheritance',2,'Figure 1'],['inheritance',4,'Qualified inheritance into a clean child'],['inheritance',5,'Coupled repair and interventions']] },
    enquiry: { title: 'Constructive enquiry', aliases: ['constructive enquiry','enquiry'], plain: 'Construct a further test when the models still fitting the observations disagree about the required action.', math: 'H(L,O)={(g,K):g∈L ∧ ∀(q,y)∈O, g(K,q)=y}; A(L,O)={K:(g,K)∈H}. Action sufficiency requires H nonempty and |A|=1. Milestone three uses n=4, c=2 and L={AND,XOR}; a supplied qualified query tree resolves represented action disagreement. Outside-library OR failures remain visible.', refs: [['enquiry',2,'§§2–3']] },
    expression: { title: 'Acquired expression', aliases: ['acquired expression','acquired expressions','expression extension'], plain: 'Audited failure supports installing an expression that the declared construction grammar can express but the working library lacks.', math: 'V(D)={g∈G:∀(K,q,y)∈D, g(K,q)=y}. Milestone four selects s≥1 from a supplied 26-program grammar using 88 calibration observations, checks 3,100 separate semantic observations, then tests new n=7/c=3 cases. The selector, interpreter and grammar remain fixed.', refs: [['enquiry',3,'§4 and §4.1']] },
    meta: { title: 'Meta-extensibility', aliases: ['meta-extensibility'], plain: 'The research target of changing the language or machinery used to construct future improvements, while retaining justified boundaries.', math: 'A change G→G′ or Constructor→Constructor′ needs a specified interpretation, dependency transport, checked obligations and current receiving authority. Stage five acquires a bounded OR-pair constructor: G₀⊆G₁, 26→47 programs; it checks 312 protected old meanings and learns a different repair on Task B. The supplied meta-grammar, primitive meanings and meta-selector remain fixed; broader self-extensibility is a research target.', refs: [['enquiry',7,'§10.2, proposed stronger developmental test'],['book',89,'§18.4, bounded meta extensibility']] },
    rate: { title: 'Relative development rate', aliases: ['relative development rate','development rate'], plain: 'A test of whether alignment development improves faster than other capability development under a defined, comparable resource measure.', math: 'A research target requiring explicit A(r), C(r), task distributions and resource r. No scalar rate, acceleration inequality or MeRSIA guarantee is established by this encounter’s 0→2 coverage gain.', refs: [['book',27,'Preface, proposed relative development'],['alignment',3,'Charged resources and improvement criteria']] }
  };
  const aliases = new Map();
  Object.entries(definitions).forEach(([id,d])=>d.aliases.forEach(a=>aliases.set(a.toLowerCase(),id)));
  let regex;
  function rebuildAliases(){
    aliases.clear();
    Object.entries(definitions).forEach(([id,d])=>d.aliases.forEach(a=>aliases.set(a.toLowerCase(),id)));
    regex = new RegExp('(?<![\\p{L}\\p{N}_])('+[...aliases.keys()].sort((a,b)=>b.length-a.length).map(a=>a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')(?![\\p{L}\\p{N}_])','giu');
  }
  function registerDefinitions(entries){
    const incoming=new Set();
    for(const [id,d] of Object.entries(entries)){
      if(definitions[id] || !d.title || !d.plain || !d.math || !Array.isArray(d.aliases) || !d.aliases.length || !Array.isArray(d.refs) || !d.refs.length)throw new Error('Invalid or duplicate term definition.');
      for(const a of d.aliases){const key=a.toLowerCase();if(aliases.has(key)||incoming.has(key))throw new Error('Duplicate definition alias.');incoming.add(key);}
      for(const [key,page] of d.refs)if(!sources[key] || !Number.isInteger(page) || page<1)throw new Error('Invalid definition source.');
    }
    Object.assign(definitions,entries);rebuildAliases();
  }
  rebuildAliases();
  const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function body(id) {
    const d=definitions[id];
    return `<h2>${escape(d.title)}</h2><h3>Plain English</h3><p>${escape(d.plain)}</p><h3>Mathematical definition / status</h3><div class="definition-math">${escape(d.math)}</div><h3>Source mathematics</h3><ul>${d.refs.map(([key,page,section])=>`<li><a href="${sources[key].file}#page=${page}" target="_blank" rel="noopener">${escape(sources[key].title)} · p. ${page}</a><span>${escape(section)}</span>${sources[key].doi ? `<a class="definition-public-link" href="${sources[key].doi}" target="_blank" rel="noopener noreferrer">Access this work on Zenodo ↗</a>` : key==='book' ? '<span>Forthcoming book; manuscript citation only.</span>' : ''}</li>`).join('')}</ul>`;
  }
  function annotate(root=document.querySelector('main')) {
    if(!root)return;
    const nodes=[];
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){
      return node.parentElement && !node.parentElement.closest('button,a,select,option,script,style,summary,textarea,svg,.definition-dialog,.term-popover,[data-no-terms]') && node.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    }});
    while(walker.nextNode())nodes.push(walker.currentNode);
    for(const node of nodes){
      const text=node.textContent; regex.lastIndex=0;
      const matches=[...text.matchAll(regex)]; if(!matches.length)continue;
      const fragment=document.createDocumentFragment();let last=0;
      for(const match of matches){
        fragment.append(document.createTextNode(text.slice(last,match.index)));
        const button=document.createElement('button');button.type='button';button.className='term';button.dataset.term=aliases.get(match[0].toLowerCase());button.textContent=match[0];
        button.setAttribute('aria-label','Define '+match[0]);button.setAttribute('aria-haspopup','dialog');fragment.append(button);last=match.index+match[0].length;
      }
      fragment.append(document.createTextNode(text.slice(last)));node.replaceWith(fragment);
    }
  }
  let popup,dialog,content,hideTimer;
  function dismiss(){clearTimeout(hideTimer);if(popup)popup.hidden=true;}
  function showHover(button){
    clearTimeout(hideTimer);if(dialog.open)return;
    popup.innerHTML=body(button.dataset.term);popup.hidden=false;
    const rect=button.getBoundingClientRect();const width=Math.min(390,window.innerWidth-24);
    popup.style.width=width+'px';popup.style.left=Math.min(Math.max(12,rect.left),window.innerWidth-width-12)+'px';
    const height=popup.getBoundingClientRect().height;
    popup.style.top=(rect.bottom+height+12<window.innerHeight ? rect.bottom+8 : Math.max(12,rect.top-height-8))+'px';
  }
  function show(id){dismiss();content.innerHTML=body(id);if(!dialog.open)dialog.showModal();}
  function showGlossary(){dismiss();content.innerHTML='<h2>Definitions and source mathematics</h2><p>Choose a concept. Each entry separates its plain-English meaning, mathematical definition or research status, and source pages.</p><div class="glossary-list">'+Object.entries(definitions).sort((a,b)=>a[1].title.localeCompare(b[1].title)).map(([id,d])=>`<button type="button" class="term glossary-entry" data-term="${id}">${escape(d.title)}</button>`).join('')+'</div>';if(!dialog.open)dialog.showModal();}
  function initialise(){
    popup=document.createElement('div');popup.className='term-popover';popup.hidden=true;popup.setAttribute('role','tooltip');popup.id='term-popup';document.body.append(popup);
    dialog=document.createElement('dialog');dialog.className='definition-dialog';dialog.innerHTML='<button type="button" class="secondary definition-close">Close definition</button><div class="definition-content"></div>';
    dialog.setAttribute('aria-label','Term definition and source mathematics');document.body.append(dialog);content=dialog.querySelector('.definition-content');
    dialog.querySelector('button').addEventListener('click',()=>dialog.close());
    document.addEventListener('click',e=>{const button=e.target.closest('.term');if(button){e.preventDefault();e.stopPropagation();show(button.dataset.term);}});
    document.addEventListener('pointerover',e=>{const button=e.target.closest('.term');if(button && e.pointerType!=='touch')showHover(button);});
    document.addEventListener('pointerout',e=>{if(e.target.closest('.term')&&!popup.contains(e.relatedTarget))hideTimer=setTimeout(dismiss,180);});
    popup.addEventListener('pointerenter',()=>clearTimeout(hideTimer));popup.addEventListener('pointerleave',dismiss);
    document.addEventListener('focusin',e=>{const button=e.target.closest('.term');if(button)showHover(button);});
    document.addEventListener('focusout',e=>{if(e.target.closest('.term')&&!popup.contains(e.relatedTarget))dismiss();});
    document.addEventListener('keydown',e=>{if(e.key==='Escape')dismiss();});
    window.addEventListener('resize',dismiss);window.addEventListener('scroll',dismiss,{passive:true});
    annotate();
  }
  window.OrchardGuidance=Object.freeze({annotate,show,showGlossary,registerDefinitions,sources,definitions});
  document.addEventListener('DOMContentLoaded',initialise);
})();
